import styled from '@emotion/styled';

export const StyledSummaryForPowerPerformance = styled.div({
  display: 'flex',
  flexDirection: 'row',
});

interface StyledChartContainerProps {
  $isExportPage?: boolean;
}

export const StyledChartContainer = styled('div', {
  shouldForwardProp: (propName) => propName !== '$isExportPage',
})<StyledChartContainerProps>(({ $isExportPage }) => ({
  height: '300px',
  ...($isExportPage && { height: '300px' }),
}));

interface StyledYearPowerAcVariationProps {
  $hideOverflow?: boolean;
}

export const StyledYearPowerAcVariation = styled('div', {
  shouldForwardProp: (propName) => propName !== '$hideOverflow',
})<StyledYearPowerAcVariationProps>(({ $hideOverflow }) => ({
  marginBottom: '48px',
  ...($hideOverflow && { marginBottom: '16px' }),
}));

interface StyledTrendOverTimeVariationProps {
  $hideOverflow?: boolean;
}

export const StyledTrendOverTimeVariation = styled('div', {
  shouldForwardProp: (propName) => propName !== '$hideOverflow',
})<StyledTrendOverTimeVariationProps>(({ $hideOverflow }) => ({
  ...($hideOverflow === true && { marginBottom: '0' }),
  ...($hideOverflow === false && { marginBottom: '48px' }),
}));
